<div class="tool-grid">
    <div class="tool-field"><label>Name</label><input data-input="name" placeholder="Your name"></div>
    <div class="tool-field"><label>Phone</label><input data-input="phone" placeholder="+254..."></div>
    <div class="tool-field"><label>Town / estate</label><input data-input="location" placeholder="Nairobi, Westlands"></div>
    <div class="tool-field"><label>Site type</label><select data-input="site"><option>Home</option><option>Office</option><option>School</option><option>Estate</option><option>Warehouse</option><option>ISP / contractor</option></select></div>
    <div class="tool-field"><label>Service needed</label><select data-input="service"><option>New fiber installation</option><option>Fiber troubleshooting</option><option>Splicing and termination</option><option>Loss testing / OTDR</option><option>Router or Wi-Fi setup</option><option>CCTV over fiber</option></select></div>
    <div class="tool-field"><label>Urgency</label><select data-input="urgency"><option>Normal</option><option>This week</option><option>Urgent</option></select></div>
    <div class="tool-field" style="grid-column:1/-1"><label>Notes</label><textarea data-input="notes" placeholder="Describe the route, issue, distance, or affected users"></textarea></div>
</div>
<button class="tool-button mt-3" type="button" data-calculate>Prepare Request</button>
